-- 우리집 건강노트: Supabase 테이블, 보안 규칙, 예시 데이터
-- Supabase 대시보드 > SQL Editor 에 통째로 붙여 넣고 Run 하세요. 여러 번 실행해도 괜찮아요.

create table if not exists public.health_docs (
  path text primary key check (char_length(path) <= 300),
  parent text not null,
  data jsonb not null check (pg_column_size(data) < 200000),
  updated_at timestamptz not null default now()
);
create index if not exists health_docs_parent_idx on public.health_docs (parent);

alter table public.health_docs enable row level security;
grant select, insert, update, delete on public.health_docs to anon, authenticated;

drop policy if exists "health_docs read" on public.health_docs;
drop policy if exists "health_docs visitor insert" on public.health_docs;
drop policy if exists "health_docs visitor update" on public.health_docs;
drop policy if exists "health_docs visitor delete" on public.health_docs;

-- 누구나 읽기 가능 (공개 데모)
create policy "health_docs read" on public.health_docs for select to anon, authenticated using (true);
-- 방문자는 members/v_로 시작하는 방문자 공간에만 쓸 수 있고, 예시 가족(members/demo-…)은 고칠 수 없음
create policy "health_docs visitor insert" on public.health_docs for insert to anon, authenticated
  with check (path ~ '^members/v_[a-z0-9]{8,24}(/|$)' and parent = regexp_replace(path, '/[^/]+$', ''));
create policy "health_docs visitor update" on public.health_docs for update to anon, authenticated
  using (path ~ '^members/v_[a-z0-9]{8,24}(/|$)')
  with check (path ~ '^members/v_[a-z0-9]{8,24}(/|$)' and parent = regexp_replace(path, '/[^/]+$', ''));
create policy "health_docs visitor delete" on public.health_docs for delete to anon, authenticated
  using (path ~ '^members/v_[a-z0-9]{8,24}(/|$)');

-- 실시간 반영
do $$ begin
  alter publication supabase_realtime add table public.health_docs;
exception when duplicate_object then null; end $$;

-- 예시 가족 데이터 (아빠·엄마·딸, 2026-10-21 기준 날짜 — 화면에서는 접속한 날에 맞춰 자동으로 옮겨져요)
on conflict (path) do update set data = excluded.data, parent = excluded.parent, updated_at = now();
